/** Shared frame for the non-home tabs: a title and short intro, centered in the panel like the home tab. */
function TabBody({ title, intro, children, footer }: { title: string; intro: ReactNode; children: ReactNode; footer?: ReactNode }) {
  return (
    <>
      <div className="pt-14 sm:pt-20 xl:my-auto xl:pt-0">
        <h2 className="font-display text-[2.5rem] leading-[1] font-semibold tracking-[-0.03em] text-balance text-ink-100 sm:text-5xl 2xl:text-6xl">
          {title}
        </h2>
        <p className="mt-5 max-w-[30rem] text-[1.0625rem] leading-relaxed text-ink-400 2xl:max-w-[34rem] 2xl:text-lg">{intro}</p>
        <div className="mt-10 2xl:mt-12">{children}</div>
      </div>
      {footer && <div className="mt-10 text-sm text-ink-500 xl:mt-0">{footer}</div>}
    </>
  );
}

/** A short list of points: a bold line and one plain sentence each. Numbered only when it is a sequence. */
function Points({ items, numbered = false }: { items: { title: string; body: ReactNode; art?: ReactNode }[]; numbered?: boolean }) {
  return (
    <ol className="max-w-[34rem] space-y-6 2xl:max-w-[38rem] 2xl:space-y-7">
      {items.map((item, i) => (
        <li key={item.title} className="flex items-center gap-5">
          {item.art && <div className="w-32 shrink-0 sm:w-44 2xl:w-52">{item.art}</div>}
          <div className="flex gap-4">
            {numbered && (
              <span className="font-display text-xl leading-7 font-semibold text-accent tabular-nums 2xl:text-2xl 2xl:leading-8">{i + 1}</span>
            )}
            <div>
              <h3 className="font-display text-xl leading-7 font-semibold tracking-tight text-ink-100 2xl:text-2xl 2xl:leading-8">{item.title}</h3>
              <p className="mt-1 leading-relaxed text-ink-400 2xl:text-lg">{item.body}</p>
            </div>
          </div>
        </li>
      ))}
    </ol>
  );
}

function HowTab({ onTry }: { onTry: () => void }) {
  return (
    <TabBody title="How it works" intro="Earshot listens to the tab itself, so it works even when a video has no captions.">
      <Points
        numbered
        items={[
          { title: "Paste a link", body: "Any YouTube video or livestream.", art: <PasteArt /> },
          { title: "Click Start captions", body: "Earshot asks Chrome for this tab only.", art: <StepArtStart /> },
          { title: "Share the tab’s audio", body: "Pick “This tab” and keep audio on.", art: <StepArtPicker /> },
        ]}
      />
      <button
        type="button"
        onClick={onTry}
        className="mt-10 inline-flex h-12 items-center rounded-xl bg-accent px-6 font-semibold text-accent-ink transition-colors hover:bg-accent-strong"
      >
        Paste a link
      </button>
    </TabBody>
  );
}

function PrivacyTab() {
  return (
    <TabBody
      title="Your audio, your call"
      intro="Earshot only listens when you ask, and keeps nothing."
      footer="Earshot is open source. Captions by Deepgram Nova-3."
    >
      <Points
        items={[
          { title: "Only the tab you pick", body: "Nothing is heard until you choose a tab and press Share." },
          { title: "Only to Deepgram, only while on", body: "Audio goes to Deepgram for captions and stops when you stop." },
          { title: "Nothing is saved", body: "Transcripts stay in your tab and vanish when you close it." },
        ]}
      />
      <ul className="mt-6 max-w-[34rem] text-sm leading-relaxed text-ink-500">
        <ByokNote />
      </ul>
    </TabBody>
  );
}

function ExtensionTab() {
  const code = "rounded-md bg-ink-850 px-1.5 py-0.5 text-[0.9em] text-ink-200";
  return (
    <TabBody
      title="Captions on YouTube itself"
      intro="For videos that won’t play outside youtube.com. Captions appear on the page, with the transcript in a side panel."
      footer="Works in Chrome and Edge on desktop. Full setup is in the README."
    >
      <Points
        numbered
        items={[
          { title: "Build it", body: <code className={code}>npm run build -w @earshot/extension</code> },
          { title: "Turn on Developer mode", body: <>In <code className={code}>chrome://extensions</code></> },
          { title: "Load unpacked", body: <code className={code}>apps/extension/.output/chrome-mv3</code> },
        ]}
      />
    </TabBody>
  );
}

