"use client";

import { useEffect, useRef } from "react";
import { ExtensionPopup } from "./ExtensionPopup";
import { PlayerControls } from "./PlayerControls";
import { HeroDemoProvider, useHeroDemo } from "./state";
import { TranscriptCard } from "./TranscriptCard";
import { VideoFrame } from "./VideoFrame";

/** The stage backdrop: a dim room with warm stage light, like the paused frame of a talk. */
function Backdrop({ className = "" }: { className?: string }) {
  return <div className={`hero-backdrop hero-focus pointer-events-none absolute inset-0 ${className}`} aria-hidden="true" />;
}

/**
 * The right side of the hero: real pieces of Heard, composed like a collage.
 *
 * On wide screens the pieces sit on a fixed 760×560 canvas that scales to fit the stage, so the
 * composition holds at every size: the video is the anchor, the controls straddle its bottom edge,
 * the transcript stands a little higher and tucks against its right edge, and the extension popup
 * drops in below the transcript. Narrower screens stack the same pieces.
 *
 * They arrive one at a time: the player, its controls, the transcript, then the popup.
 */
export function HeroDemo() {
  return (
    <HeroDemoProvider>
      <DemoLayout />
    </HeroDemoProvider>
  );
}

const CANVAS_W = 760;
const CANVAS_H = 560;
const MAX_SCALE = 1.4;

/** Scales the wide-screen canvas to fit its box (a CSS variable, so it costs no re-render). */
function useCanvasScale() {
  const boxRef = useRef<HTMLDivElement>(null);
  useEffect(() => {
    const box = boxRef.current;
    if (!box) return;
    const wide = window.matchMedia("(min-width: 1280px)");
    const update = () => {
      if (!wide.matches) {
        box.style.removeProperty("--demo-scale");
        return;
      }
      const { width, height } = box.getBoundingClientRect();
      const s = Math.min(width / CANVAS_W, height / CANVAS_H, MAX_SCALE);
      box.style.setProperty("--demo-scale", String(Math.max(0.5, s)));
    };
    update();
    const ro = new ResizeObserver(update);
    ro.observe(box);
    wide.addEventListener("change", update);
    return () => {
      ro.disconnect();
      wide.removeEventListener("change", update);
    };
  }, []);
  return boxRef;
}

function DemoLayout() {
  const { showTranscript, captionsOn, playing } = useHeroDemo();
  const listening = captionsOn && playing;
  const boxRef = useCanvasScale();

  return (
    <>
      <Backdrop className="hidden rounded-[32px] xl:block" />
      <div
        className="relative mt-14 overflow-hidden rounded-[28px] px-5 pt-9 pb-8 sm:px-10 sm:pt-12 sm:pb-12 xl:absolute xl:inset-y-0 xl:right-0 xl:left-[46%] xl:mt-0 xl:overflow-visible xl:rounded-none xl:p-0 2xl:left-[41%]"
        data-hero-demo
        role="group"
        aria-label="Try Heard: a demo player with live captions, the Chrome extension popup and the transcript"
      >
        <Backdrop className="xl:hidden" />

        {/* The box the canvas scales into: clear of the extension button above, with room all round. */}
        <div ref={boxRef} className="relative xl:absolute xl:inset-x-[5%] xl:top-28 xl:bottom-12">
          <div className="relative flex flex-col xl:absolute xl:top-1/2 xl:left-1/2 xl:block xl:h-[560px] xl:w-[760px] xl:-translate-x-1/2 xl:-translate-y-1/2 xl:[scale:var(--demo-scale,1)]">
            {/* Player: the anchor */}
            <div className="hero-pop relative xl:absolute xl:top-[64px] xl:left-0 xl:w-[560px]" style={{ animationDelay: "350ms" }}>
              <VideoFrame />
              <span
                className="absolute -top-4 -left-3 grid h-11 w-11 place-items-center rounded-full bg-ink-950 shadow-[0_8px_24px_-8px_rgba(0,0,0,0.9)] ring-1 ring-white/10"
                title={listening ? "Listening" : "Not listening"}
              >
                <span className="flex h-4 items-center gap-[3px]">
                  {[0, 1, 2, 3].map((i) => (
                    <span
                      key={i}
                      className={`w-[3px] rounded-full transition-colors ${listening ? "hero-bar bg-accent" : "h-1 bg-ink-600"}`}
                      style={{ animationDelay: `${i * 140}ms` }}
                    />
                  ))}
                </span>
              </span>
            </div>

            {/* Controls: under the video on small screens, straddling its bottom edge on wide ones */}
            <div
              className="hero-pop relative z-20 mt-4 flex justify-center xl:absolute xl:top-[379px] xl:left-[280px] xl:mt-0"
              style={{ animationDelay: "950ms" }}
            >
              <div className="xl:-translate-x-1/2 xl:-translate-y-1/2">
                <PlayerControls />
              </div>
            </div>

            {/* Transcript: a little higher than the video, tucked against its right edge */}
            <div
              hidden={!showTranscript}
              className="hero-pop relative z-10 mt-6 w-full max-w-[19rem] xl:absolute xl:top-0 xl:left-[536px] xl:mt-0 xl:h-[372px] xl:w-[224px] xl:max-w-none"
              style={{ animationDelay: "1550ms" }}
            >
              <div className="h-full xl:rotate-2">
                <TranscriptCard />
              </div>
            </div>

            {/* Chrome extension popup: drops in below the transcript, leaning the other way */}
            <div
              className="hero-pop relative z-30 -mt-4 ml-auto w-[15.5rem] xl:absolute xl:top-[392px] xl:left-[476px] xl:mt-0 xl:ml-0 xl:w-[256px]"
              style={{ animationDelay: "2150ms" }}
            >
              <div className="-rotate-2 xl:-rotate-3">
                <ExtensionPopup />
              </div>
            </div>
          </div>
        </div>
      </div>
    </>
  );
}

